(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["qu"] = {"ui":{"skip":"Ukhuman riy","back":"← AI-gilemanta kutiy","lang.button":"Simi: {name}","lang.dialog":"Simita akllay","lang.search":"Simikunata maskhay","lang.none":"Manan simi tupanchu","lang.notYet":"{name} manaraq t'ikrasqachu","theme.aria":"K'anchaq tutayaq rikch'aykunapura tikray","theme.toLight":"K'anchaq rikch'ayman tikray","theme.toDark":"Tutayaq rikch'ayman tikray","words.underline":"Kay simikunata paginapi uranmanta siqiy","words.underlineHelp":"Ch'iqchisqa simiman cursorta churay utaq llamiy, imata niyta munasqanta rikunaykipaq.","index.title":"AI-gile: AI ruraq aylluyki, huk tablerupi","index.description":"AI-gile huk kanban tablerom AI programa ruraq ayllukunapaq. Qan puñuchkaptiyki paykuna llamk'anku; qanmanqa huk pisi huñu chayamun: akllanaykipaq, pruebanaykipaq, chaskinaykipaq imakuna.","hero.logoAlt":"AI-gile tablerupa rikch'ancha","hero.h1.html":"AI ruraq aylluyki, huk&nbsp;tablerupi.","hero.alpha":"🐣 Wichqasqa ñawpaq alfa","hero.alphaTitle":"Ñawpaqmi, manaraq tukusqachu: pruebasqaykimanta añay!","hero.lede":"Qan puñuchkaptiyki paykuna ruranku. Rikch'arispaqa huk pisi huñuta tarinki: wakin tapuykuna, pruebanapaq wakin imakuna, huk utaq iskay lila diamantekuna. Ñit'iy, chaskiy, cafeykiman kutiy.","dl.windows":"Windows app","dl.browser":"Browserniykipi purichiy","dl.soon":"Usqhayllan hamunqa","dl.notify":"🔔 Kichakuptinqa willaway","dl.notifySmall":"Alfa utaq beta","hero.secondary":"Agile, ichaqa aylluqa manam stand-up cafeta munanchu. (Chaywanpas stand-upkunata ruranku.)","pitch.h2":"AI-gile munasqayki simikunapi","pitch.lede":"Huk simimanta 144-kama hayk'a hatunta akllay. Sapa hatun kayqa chay hatunpaq qillqasqa sapaq willayniyuqmi. Sliderta aysay, utaq flecha llavekunata llamk'achiy.","pitch.rangeLabel":"Simikunapi hatun kay","pitch.dice":"🎲 huk version","pitch.words.one":"{n} simi","pitch.words.other":"{n} simikuna","pitch.letters.one":"{n} qillqa","pitch.letters.other":"{n} qillqakuna","pitch.chars.one":"{n} sananpa","pitch.chars.other":"{n} sananpakuna","count.line.html.one":"kunan tablerupi {n} karta kachkan","count.line.html.other":"kunan tablerupi {n} kartakuna kachkan","features.aria":"Imatan ruran","f.pile.h":"Qanpaq huklla huñu","f.pile.html":"<b>Qanpaq</b> nisqapi llapa proyectokunamanta qanta suyaqkuna tantasqa kachkan: tapukuykuna, pruebanapaq imakuna, runallan ruranan ruraykuna. Colaykim nin imataq qatiqnin, hayk'a pachatapas apanqa.","f.sleep.h":"Qan puñuchkaptiyki llamk'aq ayllukuna","f.sleep.p":"Sapa proyectoqa pusaqniyuq, AI agentekunap aylluyuqpas. Kartapi willay, aylluqa rikch'arin, llamk'ayta ruran, sayk'usqa runapas qatinan ruraykunawan kutichimun.","f.tester.h":"AI pruebaqmi ñawpaqta qhawan","f.tester.p":"Imapas manaraq qanman chayachkaptin, huk pruebaq app copiapi ruraykunata qatispa imatachus rikusqanta rikuchin, captura de pantallawan. Pasaqkunata qhawariy, huk ñit'iyllawan chaskiy.","f.proof.h":"Rikuchiy, mana simillachu","f.proof.p":"Sapa quykuyqa imataq tikrakusqanta rikuchin: willañiqikuna, diff, capturakuna. Mana sapa appta kichaspa tukusqachu kachkan chaytachu qhawanayki.","f.chat.h":"Pusaqniykikunawan rimay","f.chat.p":"Discord hina huk muyu: sapa proyectopaq huk rikch'ancha, qanta munaqkunapaq lila diamantekuna. Pusaqman yuyayniykita kachay; paymi kartakunaman hinaspa planman tikran, ✅ Go botonwan.","f.tidy.h":"Kikinmi allichakun","f.tidy.p":"Tupaq kartakuna hukman tantakunku, chaqrusqa sutikuna allichasqa, token qhawaytaq codeta llamp'u waqaychan. Pisi imakunapura tikranayki, pisi yuyanayki.","f.private.h":"Qanpa, computadoraykipi","f.private.li1":"Tableroqa kikiyki computadoraykipim purin, qanllatataq kutichin.","f.private.li2":"Runakuna chawpipi sapaq DMkunaqa tukuy ladomanta amachasqam.","f.private.li3":"Mana cuentakuna, mana qhatiqkuna, mana cookiekuna.","f.lang.h":"Simiykipi","f.lang.p":"120 simimanta aswan, holandés, galés hinaspa japonesmanta pirata, Yoda hinaspa klingonkama, desarrolladorkunaq simikunapaq inglésman usqhay kutiywan.","f.service.h":"Huk yuyaymanta chiqap servicioman","f.service.p":"AI-wan imatapas rurarqanki, runakunataq kunan llamk'achinku? Servicio hina akllay, tableroqa allinta purichinaykipaq yanapasunki: uptime qhawaykuna, llapapaq status p'anqa, willasqa incidentekuna, Go munaq tikraykuna, sapa p'unchaw qhawasqa backupkuna. Yanapayqa sapa rurayta purisqaykiman hina yachachin.","tl.aria":"Ñawpaq rimaymanta rurana ñankama pacha tupuy","tl.h2":"Ñawpaq rimaymanta qatiqnin kama","tl.lede":"Chiqap p'unchawkuna horakunapas, kikiyki pacha zonaykipi. Kunanmanta qhipaqa planmi, mana p'unchawkuna rimanakusqachu.","tl.today":"Kunan","tl.planned":"yuyaychasqa","tl.cards.one":"{n} karta","tl.cards.other":"{n} kartakuna","join.h2":"Hukllachakuy","join.lede":"AI-gile-ta huk huch'uy runa askha pacienciayuq agentekunapas ruranku. Kunanqa sapaqmi, masikunawan wichqasqa alfapi. Kichakuptin pruebayta munankichu?","join.btn":"Munayniyta qillqachiy","join.small":"Correollata apachisqayku, manam huk imatapas","footer.tag":"AI-gile. Mana qatipaqkuna, mana cookiekuna, mana stand-up cafe.","footer.licence":"Negocio licencia","footer.status":"Imayna kasqan","footer.privacy":"Ima waqaychasqayku","form.sending":"Kachaykuchkan…","form.failed":"Manan allinchu karqan: qhepaman huktawan ruray.","form.offline":"Manan AI-gilemanta chayayta atirqanchu: qhepaman huktawan ruray.","form.keep":"Kayta kutichinaykupaqlla llamk'achiyku, chaymanta qulluyku. Mana qatipaqkuna, mana cookiekuna.","form.keepLink":"Ima waqaychasqayku","interest.title":"AI-gile: alfa kichakuptin willaway","interest.description":"Correoykita saqiy, AI-gilepa wichqasqa alfan utaq betan kichakuptin yachanaykipaq.","interest.h1":"🔔 Kichakuptinqa willaway","interest.lede":"AI-gileqa wichqasqa ñawpaq alfapin kachkan. Correoykita saqiy, qanpaq sitio kaptinqa huk kutillata qillqamusqayku.","interest.email":"Correoyki","interest.which":"Mayqin prueba?","interest.alpha":"Wichqasqa alfa: ñawpaq, mana allichasqa, askha tikrakuykunawan","interest.beta":"Beta: aswan takyasqa, qhepaman","interest.both":"Mayqinpas, ñawpaqta chayaqta","interest.submit":"Listaman churaway","interest.thanks":"Añaychayki! Listapin kanki.","licence.title":"AI-gile: negocio licencia","licence.description":"Negocioykipi AI-gilewan llank'ankichu? Mana qullqiyuq negocio licenciata mañakuy.","licence.h1":"📜 Negocio licencia","licence.lede":"Llamk'aypi AI-gile-ta llamk'achinkichu? Pi kasqaykita, ima rurasqaykitapas willawayku. Allinta ruraptinqa, licenciaqa mana qullqiyuqmi.","licence.company":"Empresa","licence.website":"Web sitio","licence.what":"Imatan ruranki","licence.how":"Kay pachata imaynatan yanapan","licence.email":"Correo","licence.submit":"Mañakuy","licence.thanks":"Añaychayki! Correopi kutichisaqku.","status.title":"AI-gile imayna kasqan","status.h1":"AI-gile imayna kasqan","status.quiet":"Llapan thak","status.intro":"AI-gile kunan llamk'achkanchu? Kay pagina sapa 5 minutopi websiteta, tablero rakinakuyta, waqyakuykunata hinaspa uraykachiyta qhawan.","status.up":"Llamk'achkan ({ms} ms-pi kutichirqan)","status.slow":"Qhipa qhawaypi mana kutichirqanchu, huktawan ruraspa","status.down":"Mana llamk'anchu: iskay qhipa qhawaykunapi mana kutichirqanchu","status.svc.web":"Website","status.svc.web.offers":"Kay website: ima AI-gile kasqan, munay formulariopas","status.svc.boards":"Tablero rakinakuy","status.svc.boards.offers":"Llapapaq tablerokuna, masikuna ukhupi willakuykuna hinaspa invitacionkuna","status.svc.calls":"Waqyakuykuna","status.svc.calls.offers":"Kunka, video hinaspa pantalla rakinakuy AI-gilepi","status.svc.download":"Uraykachiy","status.svc.download.offers":"Windows instalador hinaspa invitacion linkkuna","status.checking":"Qhawachkan…","status.offline":"Kunan manan imayna kasqan serviciuman chayayta atirqanchu (huktawan ruraspa)","status.updated":"{ago} musuqchasqa","status.justNow":"kunallan","status.min":"{n} minuto ñawpaq","status.hours":"{n} hora ñawpaq","status.days":"{n} p'unchaw ñawpaq","privacy.title":"AI-gile: ima waqaychasqayku","privacy.h1":"Ima waqaychasqayku","privacy.lede":"Pisillapi: kachamuwasqaykullata, manataq unaypaqchu.","privacy.only":"Kachamuwasqaykullata: formulariopi qillqasqaykita, correoyki hina. Manan qanmanta huk imatapas.","privacy.sealed":"Sellasqa kachkan, servidorniyku mana ñawinchananpaq: browserniykipi, manaraq lluqsichkaptin (mawk'a browserpi, chayamusqan ratu). Ñuqaykuq tableroylla kicharinman.","privacy.server":"Tableroykuman chayasqanwan servidormanta qullusqa kan. 30 p'unchaw qhipata chaypi kachkaqtaqa hinallataq qulluyku.","privacy.board":"Tableroykupi waqaychayku kutichinaykukamalla, chaymanta chaypipas qulluyku.","privacy.none":"Mana qatipaqkuna, mana cookiekuna, mana yupaykuna.","privacy.local":"Simiyki, k'anchay utaq tutayaq akllasqaykipas kikiyki browserniykipi qhipanku. Manan hayk'aqpas ñuqaykuman kachasqachu.","privacy.ask":"Usqhayllata chinkachisqa kananta munankichu? Correoykuta kutichiy hinaspa niwayku.","live.h2":"Qhaway ruwasqa kachkaqta, kawsaypi","live.caption":"Sapa kartaqa pakasqam: llank'ayninpa rikch'ayninta qhawanki, mana simikunata.","live.watching.one":"kawsaypi: {n} qhawachkan","live.watching.other":"kawsaypi: {n} qhawachkan","live.last.now":"Qhipa karta kunallan kuyusqa","live.last.min.one":"Qhipa karta {n} minutu ñawpaq kuyusqa","live.last.min.other":"Qhipa karta {n} minutu ñawpaq kuyusqa","live.last.hour.one":"Qhipa karta {n} hora ñawpaq kuyusqa","live.last.hour.other":"Qhipa karta {n} hora ñawpaq kuyusqa","live.last.day.one":"Qhipa karta {n} p'unchaw ñawpaq kuyusqa","live.last.day.other":"Qhipa karta {n} p'unchaw ñawpaq kuyusqa","live.offline":"Kawsay tablaqa uchuy samarichkan. Chaylla kutimuy.","live.cols":"Backlog|Ruranaykuna|Ruraypi|Ayllu qhawashan|Qanpaq test ruranapaq|Ayllupaq|Tukusqa"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotkuna.","Hayñisqa."]},{"n":2,"texts":["Robot kanban.","Agentekuna, allichasqa.","Yuyaykuna, rurasqa."]},{"n":3,"texts":["Robotkunapaq kanban.","Yuyaykuna ruraykunaman tikrakun.","Mana qullqiyuq agente kanban."]},{"n":5,"texts":["Agentekuna pusasqa kanban tablero.","Qan kartata qillqay. Agentekuna ruranku.","Mana qullqiyuq, kayllapi, yachasqa, asikuyniyuq."]},{"n":8,"texts":["Mana qullqiyuq kanban tablero, AI agentekuna chaypi llank'anku.","Yuyayta qillqay. Agentekuna rurankuman. Qan chaskinki.","Huk runapaq hinaspa askha pacienciayuq robotkunapaq agile."]},{"n":13,"texts":["Kikiyki computadorpi kanban tablero kachkan, chaypi AI agentekuna kartakunata hap'ispa sapa p'unchaw llank'anku.","Huk yuyayta qillqay. Agentekunaq huk aylluqa chayta rurankum. Chaymanta huk yachaqqa allinchus qhawanqa.","Mana qullqiyuq, mana cuentayuq, mana qhatiqyuq: huk tablero, wakin robotkuna, hinaspa qan kamachiq kanki."]},{"n":21,"texts":["AI-gile kanmi AI programa agentekunawan llank'ay munaqkunapaq huk kanban tablero. Agentekunam kartakunata hap'inku, qantaq chaykunata yachaykuspa chaskinki.","Sapa proyectoqa huk pusaqniyuqmi, hinaspa AI agentekunaq huk aylluyuqmi. Mayqin kartapipas rimariy, chaymi chay ayllu usqhayllan llank'ayta qallarin.","Kikiyki computadorpi purin kay mana qullqiyuq sapaq ruraykuna tablero. Llank'aqkunaqa robotkunam. Ichaqa arí nispa niqqa, qanmi kanki."]},{"n":34,"texts":["Qan yuyaykunata huk tablerupi churanki. AI agentekunaq aylluqa chay yuyaykunata allinta llank'aq ruraykunaman tikran, yachaykun, hinaspa ruraspa qatinapaq ñampikunawan qanman kutichimun. Qan arí ninaykikama, manan imapas tukusqa nisqachu kanqa.","AI-gile kanmi wasipi ruwasqa kanban tablero, Richmi chayta rurarqan askha yanapayniyuq agentekunawan, kunantaq paykunata kamachin. Mana qullqiyuqmi, kikiyki computadorpi purin, amigokunawanmi rakinakun, manan qhatukunchu. Chayrayku mana ima chanintapas mañakunchu.","Huk simpa kanban tableroyta yuyaykuy, columnakunataq Backlogmanta Tukusqakama kachkan, ichaqa kartakunata AI agentekuna hap'inku. Ñawpaqman rinankuta willanku, wichqasqa kaptinku tapunku, hinaspa sapa kuti qan arí ninaykita suyanku."]},{"n":55,"texts":["AI-gile kanmi huk kanban tablero, chaypi llapa ayllun AI agentekunamanta ruwasqa kachkan. Sapa proyectoqa huk pusaqniyuqmi, paymi llank'ayta yuyaychan, yanapaqninkunataq chayta ruranku. Huk rurayqa wakichisqa kaptin, huk AI yachaqmi chayta yachaykun hinaspa captura de pantallata hap'in, chaymantam qanpa t'inkaykiman chayamun. Chaskiy, utaq rimariy, chaymi paykuna huktawan ruranqaku.","Ñawpaqtaqa huk runaq yuyaynin karqan: askha AI programa llank'aykunata huk pachallapi qatinanpaq. Chaymantam chiqap tablero hinaman wiñarqan. Kikiyki machinapin purin, manan cuentata mañakunchu, manataqmi qhatiqniyuqchu. Amigokunapaq hinaspa yachayta munaqkunapaqmi mana qullqiyuq. Manataqmi tukusqachu, chayraykum rakhu kuskankunata hinaspa wakin kutikuna musphayta suyakuy. Chaymi allin, wakin rimariy qallariypaq.","Chiqaptan rimasun. Yuyaykunaqa qanpam kachkan, rurasqakunatapas qanmi qhawanayki. AI-gile ruran chawpipi tukuy imata: kartakunata allin ñiqinpi tiyachin, rimariykita rikuspa allin agenteta rikch'arichin, imataq tikrakusqanta pacha rikuchin, hinaspa llapa chaykunata qanpaq huk pisi t'inkaman tantan. Chay hinapin qan astawan allin yuyaykunapi kakunki, manataq sapa p'unchaw tukuy ruraykunata qatispa sayk'unkichu, sumaqta samarispa."]},{"n":89,"texts":["AI-gile kanmi mana qullqiyuq kanban tablero, chaytan kikiyki computadorpi purichinki. Runakunaq rantinpi, sapa proyectoqa AI agentekunaq huk aylluyuqmi: huk pusaq yuyaykuykikunata kartakunaman hinaspa planman tikran, yanapaqkunataq kartakunata ñawpaqnin kaqmanta hap'inku. Imapas rurasqa kaptin, huk AI yachaqmi yachay ñampikunata qatin hinaspa imatan rikusqanta qanman rikuchin. Chaymanta Qanpaq sutiyuq huk t'inkapi suyan. Qan chaskinki, utaq rimarinki chaymi ayllu huktawan ruran. Qan mana kaspaqa, imapas manan Tukusqamanqa chayanchu. Chhaynatam qan, mana sayk'uspa, tukuy proyectokunata huk qhawaypi riqsinki.","Wakin ruraykuna mana suyasqayki kanman. Tuta qhawaqqa qan puñuptiyki Ruranaykuna columnata hunt'asqa tiyachin, qanpa kutichiyniykita mana munaq kartakunata akllaspa. Huk token yupaqmi rikuchin agentekuna kunan hinaspa kay semanapi hayk'a llamk'asqankuta, Mana Token Modoqa paykunata qullqi usuchiyta sayachinankupaq niyta. Amigokunaman willayta kachayta atinki, hinaspa sapaq willaykunaqa tukuy ladomanta amachasqam. Tableroqa 120 simipi rimanmi, holandés, flamenco, pirata hinaspa klingonmanta qallarispa. Kaykunamanta mana huk qullqipas yanqachu, manataq pipas qanman chayta rantichiyta munanchu. Chaykunaqa huch'uy yanapaykuna, ichaqa sapa p'unchaw llamk'ayta aswan llamp'u ruranku.","AI-gileqa huch'uy sapaq proyectom, manan empresachu. Richqa wakin AI programa proyectokunata qhawariyta munarqan, ichaqa sapa app kichaspa qhawarinanpaq mana munarqanchu. Chayrayku paypas agentekunapas huk tablerota rurarqaku, chaymantataq chay tablerowan wakin partenta kikin rurarqaku. Kunan wichqasqa ñawpaq alfapi kachkan, chaymi huk chhika amigokunapaq, aswan hukkuna, llank'an. Manan chaninkuna p'anqachu kachkan, manan willakuy t'aqachu, nitaq wiñaypaq planchu. Chay allinpaq rikch'akuptinqa, aswan kichakuptin yachayta mañakuyta atinki. Chaywanpas kusikuspa llank'asqayku, hinaspa amigokunaqa kunanpas sapa p'unchaw yanapawanku."]},{"n":144,"texts":["AI-gile kanmi huk runapaq hinaspa askha AI agentekunapaq kanban tablero. Kikiyki computadorpi purin, hinaspa llapanmi mana qullqimanta. Qan proyectokunata yapanki, sapa proyectotaq huk pusaqta hinaspa huch'uy aylluta chaskin. Pusaqwan Discord hina rimanki, hinaspa huk yuyayta willanki; pusaqmi chayta kartakunaman hinaspa planman tikran, chaymanta qan Go ñit'inaykikama suyan. Ayllu kartakunata allin ñiqinpi llank'an, simi modelokunapaq rurasqa llamp'u comando linewan. Imapas qanman kutimunanpaq, huk AI yachaqmi app copiapi ñampikunata qatin hinaspa captura de pantallata hap'in. Tukusqa llank'ayqa t'inkaykiman chayamun, tikrasqa willañiqikunawan hinaspa diffwan. Qan chaskinki, utaq huk rimariyta saqinki, ayllutaq rikch'arispa huktawan ruran. Qanllan huk kartata Tukusqaman apayta atinki. Chhayna, qan kamachiqmi kanki, agentekunataq paciencianwan qanpa munayniykita huntachinku, mana sayk'uspa, mana qhawarisqa. Manan pipas ruranqachu qanta mana arí nichkaptiyki, nitaq imapas pakallapi ruranqachu.","Huk p'unchaw AI-gilewan, aswan pisi hina. Chisiyaqpi wakin rimariykunata saqinki: kay boton mana allin kankunapi kachkan, chay lista ñiqichasqa kanan, tutayaq modo atikunmanchu. Hinaspa puñuq rinki. Agentekuna rimariykunata ñawinchanku, tikraykunata ruranku, yachaykunku hinaspa qanman kutichimunku. Ruranaykuna chusaqyaptin, tuta qhawaqqa backlogmanta kartakunawan chay columnata hunt'achin, chaykunaqa qanpa kutichiyniykita mana munankuchu. Tutamanta huk pisi t'inka tiyan: wakin tapukuykuna hinaspa wakin yachaykunapaq imakuna, sapankaqa puñuyniyuq runapas qatiy atinan ñampikunayuq hinaspa llank'aqta rikuchiq captura de pantallayuq. Qan ñit'ispa riki, allinkunata chaskinki, wakinkunatataq kutichinki. Huk token yupaqmi rikuchin tukuy chaykuna hayk'a usuchisqanta, Mana Token Modotaq pisi semanakunapaq kachkan. Chaymanta ch'isi mikhunaykita mikhunki, chaypiqa agentekuna manaraq yanapayta atinkuchu. Chhaynapi qan samarispa mikhunki, agentekunataq paykunapa ruraykunata qatispa qanpaq wakichinku, tukuy p'unchaw. Chay hinallatan sapa p'unchaw kutimun.","Ñawpaqta, AI-gile mana ima kasqanta willasqayki. Manan startupchu, manan rantinapaqchu, manataqmi pipas willayniykikunata tantanchu. Mana qullqiyuq tablerom, kikiyki computadorpi purin, mana cuentayuq, mana qhatiqyuq, mana cookieyuq. Ima kasqantaq kay: huk allin ñiqichasqa llaqta, tukuy AI programa proyectokunata huk kutilla rikunaykipaq, chaypi agentekunaq aylluqa kartakunata ruran, qantaq kamachikunki. Tupaq kartakunata huñun, chaqruy sutikunata allichan, hinaspa programa hayk'a llamp'u kasqanta qhawan. Pachaq iskay chunka simita rimanmi, holandés hinaspa flamencomanta pirata hinaspa klingonkama. Amigokunaqa sapa hukninku willayta kachayta atinku, sapaqta hinaspa amachasqa. Richwan hinaspa askha pacienciayuq agentekunawanmi rurasqa, aswan kikinmanta llamk'achispa. Wichqasqa ñawpaq alfapin kachkan, chayrayku wakin kuskankunapi rakhu. Kusiq rikch'akuptinqa, sumaqta mañakuy chaymi ñawpaqmanta yaykunki. Chaymi tukuy kay: huk huch'uy, sumaq, mana qullqiyuq yanapaq, qanpa proyectokunata allinta qhawarinanpaq."]}],"quips":{"1":"Huk simi. Callpasapa. Icha aswan callpasapa.","3":"Kimsa simi. Ñawpaqtan aswan chiqap llapa rantina p'anqakunamanta.","8":"Pusaq simi. Stand-upmantapas aswan pisi.","21":"Hatun kaykunaqa story pointskuna, chaynallatan. Arí, imatan.","55":"Phisqa chunka phisqayuq simi. Ñawinchaspayki iskay karta tukukurqan.","144":"Kayqa hatun kaqmi. 233 manan kanchu. Agentekunan puñuq rirqaku."}},"timeline":{"first-idea.name":"Ñawpaq yuyay","first-idea.line":"Ñawpaqpa ñawpaq rimay, manaraq ima programapas kashaqtin.","first-board.name":"Ñawpaq tablero","first-board.line":"Huk tablero kikin ruraynintan qatispa: kartakuna, columnakuna, llamispa saqiy, proyectokuna.","team-roles.name":"Ayllu hinaspa rolkuna","team-roles.line":"Agentekunap perfilninkuna, ayllu plantillakuna, espaciokuna hinaspa pitaq ima ruran.","install.name":"Churay hinaspa lluqsichiy","install.line":"Huk zip amigo churaykuyta atinan, kikin musuqchakuy, canalkuna hinaspa qhepaman kutiy.","usage-saver.name":"Llamk'ay waqaychay","usage-saver.line":"Ruraykuna hayk'a chanin tupuy, programa llamp'u kachun, ruray kamayki waqaychay.","friends.name":"Amigokuna hinaspa rakinakuy","friends.line":"Sapaq DMkuna, pakasqa relay, qayaykuna, rolkuna hinaspa rakisqa proyectokuna.","languages.name":"Simikuna","languages.line":"Sapa pantalla qillqa huk simi willañiqipi, ñawpaqta holandés hinaspa flamenco.","ai-tester.name":"AI yachaq","ai-tester.line":"Huk yachaqmi sapa quykuyta ñawpaqta qhawan hinaspa imatan rikusqanta rikuchin.","website.name":"Web sitio","website.line":"aigile.lol, ñawpaq rikuchina pacha hinaspa kay pacha tupuy.","streaming.name":"Rimay hinaspa streaming","streaming.line":"Discord, Twitch, OBS, streamer modo, GIFkuna hinaspa emojikuna.","no-ai.name":"Mana AIyuq edicion","no-ai.line":"AI mana kaspa programachaqkunapaq huk tablero, hinaspa llapa runaq tablerukuna.","night-watch.name":"Tuta qhawaq","night-watch.line":"Huk qhawaq hinaspa Scrum Master qan puñuptiyki ayllukunata llank'aypi tiyachin.","p-more.name":"Llapa wakin","p-more.line":"Aswan huch'uy yuyaykuna, kuticha suyaspa.","p-android.name":"Celular hinaspa Android","p-android.line":"Tableruykiman celularmanta chayay, chaymanta kikin Android app.","p-release.name":"Alfa hinaspa aswan","p-release.line":"Wichqasqa alfa, kawsaq web sitio, chaymanta beta.","p-languages.name":"Aswan simikuna","p-languages.line":"Pachaqmanta aswan simikuna, hinaspa yachaqkunapaq ukhu yachay modo.","p-engines.name":"Aswan AI motorkuna","p-engines.line":"Sapa agentepaq Claude, Codex utaq Gemini akllay.","p-pro.name":"Llank'ay yachay","p-pro.line":"Manchay rikch'aykuna, merge punkukuna, pantay kartakuna hinaspa amachaykuna.","p-self.name":"Qanta qhawariy","p-self.line":"Sayk'uy modo, kikiyki qhawarispa yuyarichiykuna hinaspa 4:20.","p-servers.name":"Servidorkuna hinaspa hatun kay","p-servers.line":"Llapa pacha servidor churayniykuna, rolkuna hinaspa wiñayta yuyaychay.","p-livestream.name":"Streaming yapaykuna","p-livestream.line":"Twitch rimay, kikin emojikuna hinaspa llapa runaq kawsaq qhawana."},"words":{"button":"📖 Dev simikuna","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Simita maskay…","none":"Mana simi tupanchu.","close":"Wichqay","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Proyectop code folderninpas, commitkunap hunt'a willayninpas, sapa kuti GitHubpi waqaychasqa.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Codepi t'aqa llamk'ay ñan, tikraykuna ruranapaq hatun versionta mana llamiy.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Codep waqaychasqa rikch'aynin, imachus tikrakurqan pisi willaywan. Sapa kuti chayman kutiyta atinki.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Waqaychasqa rikch'aykunata (commits) kay computadoramanta GitHubman apachiy, backup hinaspa rakisqa kananpaq."},{"id":"merge","g":"build","word":"Merge","text":"Branchpa tikrayninkunata hatun versionman hukllachay."},{"id":"pr","g":"build","word":"Pull request","text":"Branchpa tikraykunata qhawasqa hinaspa hatun versionman tinkichisqa kananpaq mañakuy.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Codeta allichay, imachus ruranan mana tikraspa: aswan huch'uy willañiqikuna, aswan sut'i sutikuna, pisi kutipay."},{"id":"bug","g":"build","word":"Bug","text":"Imachus ruranan hinaqa mana ruraq.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Tukusqa llamk'ayta pruebay, mañasqa hina ruraptinchus qhawanapaq, chaskinaykiman.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Musuq versionta kausaypi churay, ej. servidorpi runakuna llamk'achinankupaq."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Yuyaykuna hinaspa manaraq yuyaychasqa ruranakuna. Chaypi mana imapas ruwakunchu Ruranaykuna kaqman rinankama."},{"id":"sprint","g":"team","word":"Sprint","text":"Pisi llamk'ay pacha (sapa kuti huk utaq iskay simana) tukunapaq kartakunawan.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Pisi tapukuy: sapa ayllu masi imata rurarqan, imata qatiqninpi ruranqa, imataq hark'an.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Columnakunayuq tablero (Ruranaykuna, Ruraypi, Tukusqa), chaypi kartakuna lluq'imanta pañaman purinku llamk'ay puriptin."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: huk columna aswan hayk'a kartakunata hap'inan, ayllu aswan qallariymanta ñawpaqta tukunanpaq.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Kikin huk rurayta llamk'aq AI: codeta ñawinchan, tikrayta ruran, qhawaykunata purichin, willakun.","also":["agentes"]},{"id":"token","g":"team","word":"Token","text":"AI llamk'achiy yupana unidad: ñawinchasqa utaq qillqasqa yaqa iskay kimsa qillqakuna. Pisi token, aswan plan puchun.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Pisi kamachiy, takyasqa pachapi kikinmanta purin, ej. AI sesión qallarishaqtin, ayllu willaykunata uyarinanpaq.","also":["hooks"]}]}};
